<span class="line"><span style="color:#ABB2BF;">mistral_tok </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> AutoTokenizer.</span><span style="color:#61AFEF;">from_pretrained</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;mistralai/Mistral-7B-v0.1&quot;</span><span style="color:#ABB2BF;">)</span></span>
